const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Alsek Lake coordinates: approximately 59.10° N, 137.60° W
  const alsekLake = ee.Geometry.Point(-137.60, 59.10).buffer(15000); // 15 km buffer around the lake

  const year1 = 1984;
  const year2 = 2010;

  // 2. Data Acquisition
  const gswYearly = ee.ImageCollection('JRC/GSW1_4/YearlyHistory');

  // Function to get water extent for a given year
  const getWaterExtent = (year, geometry) => {
    const yearImage = gswYearly.filter(ee.Filter.eq('year', year)).first();

    if (!yearImage) {
      return {
        image: null,
        pixels: 0,
        area: 0
      };
    }

    // Water class description:
    // 0: No Water
    // 1: Permanent Water
    // 2: Seasonal Water
    // 3: New Permanent
    // 4: New Seasonal
    // 5: Lost Permanent
    // 6: Lost Seasonal
    // We consider any water class > 0 as water.
    const waterMask = yearImage.select('waterClass').gt(0);

    // Calculate the area of water pixels
    // Use a fixed scale for consistency and to avoid memory issues for large polygons
    // Water pixels have value 1, non-water 0.
    const waterAreaSqM = waterMask.multiply(ee.Image.pixelArea())
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: 1000, // 1000m resolution for area calculation
        maxPixels: 1e9
      }).get('waterClass'); // 'waterClass' is the band name after selection

    const waterPixels = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(), // Count of pixels where waterMask is 1
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    }).get('waterClass');

    return {
      image: yearImage,
      pixels: waterPixels,
      area: waterAreaSqM
    };
  };

  const waterData1984 = getWaterExtent(year1, alsekLake);
  const waterData2010 = getWaterExtent(year2, alsekLake);

  // Check for C1: Empty Collection
  if (!waterData1984.image) {
    console.log(`No data found for ${year1}.`);
    console.log("C1");
    return;
  }
  if (!waterData2010.image) {
    console.log(`No data found for ${year2}.`);
    console.log("C1");
    return;
  }

  const area1984 = await ee.Number(waterData1984.area).getInfo();
  const pixels1984 = await ee.Number(waterData1984.pixels).getInfo();
  const area2010 = await ee.Number(waterData2010.area).getInfo();
  const pixels2010 = await ee.Number(waterData2010.pixels).getInfo();

  // Check for C2: No Valid Pixels
  if (pixels1984 === 0) {
    console.log(`No valid water pixels found for ${year1} after processing.`);
    console.log("C2");
    return;
  }
  if (pixels2010 === 0) {
    console.log(`No valid water pixels found for ${year2} after processing.`);
    console.log("C2");
    return;
  }

  // Check for C3: Calculation Failure
  if (area1984 === null || isNaN(area1984) || area2010 === null || isNaN(area2010)) {
    console.log("Water area calculation failed (null or NaN result).");
    console.log("C3");
    return;
  }

  console.log(`Water extent ${year1}: ${area1984 / 1e6:.2f} sq km (Pixels: ${pixels1984})`);
  console.log(`Water extent ${year2}: ${area2010 / 1e6:.2f} sq km (Pixels: ${pixels2010})`);

  // 5. Validation & Final Answer
  if (area2010 < area1984) {
    console.log("A"); // Yes, water extent decreased
  } else {
    console.log("B"); // No, water extent did not decrease (either increased or stayed the same)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
